/* ===== Motion layer ===== */
/* Uncorked motion layer. Initial hidden states only apply when JS adds .mo to <html>. */
.btn{position:relative;overflow:hidden}
.btn:after{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(105deg,transparent 35%,#ffffff45 50%,transparent 65%);transform:translateX(-120%)}
.btn:hover:after{transform:translateX(120%);transition:transform .8s var(--ease)}

/* Loader: counter + curtain */
.pre{position:fixed;inset:0;z-index:300;background:var(--wine);color:var(--paper);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;transition:transform 1s var(--ease)}
.pre.done{transform:translateY(-100%)}
.pre-n{font:clamp(80px,18vw,200px)/.9 var(--serif);letter-spacing:-.05em}
.pre-n small{font-size:.3em;margin-left:6px;vertical-align:top}
.pre p{font-size:10px;letter-spacing:.3em;color:#e2cdd0}
.pre-bar{width:min(260px,60vw);height:1px;background:#ffffff30}
.pre-bar u{display:block;height:100%;background:var(--paper);transform:scaleX(0);transform-origin:left}

/* Split headline reveal */
.w{display:inline-block;overflow:hidden;vertical-align:top;padding-bottom:.12em;margin-bottom:-.12em}
.wi{display:inline-block}
.mo .wi{transform:translateY(112%) rotate(4deg);transform-origin:left bottom;transition:transform 1.1s var(--ease) calc(var(--i)*70ms)}
.mo .go .wi{transform:none}
.mo .headline{animation:none}
h1 em .wi,h2 em .wi{background:linear-gradient(100deg,var(--c,#674550) 40%,#d9a3b2 50%,var(--c,#674550) 60%) 100%/250% 100%;-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;animation:shine 6s 1.5s ease-in-out infinite}
.atmosphere em{--c:#d7b7a0}
@keyframes shine{0%,30%{background-position:100% 0}70%,100%{background-position:0 0}}

/* Masked image reveal + tilt */
.mo .hero .bar-photo{clip-path:inset(0 0 100% 0)}
.mo .hero.go .bar-photo{clip-path:inset(0);transition:clip-path 1.4s var(--ease) .2s,transform .35s ease-out}
.bar-photo{will-change:transform}
.package{transition:transform .35s ease-out}

/* Hero pointer glow */
.hero .glow{position:absolute;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(520px circle at var(--hx,50%) var(--hy,35%),#ffffffa0,transparent 62%)}

/* Spotlight border */
.services article,.package,form{position:relative}
.services article:before,.package:before,form:before{content:'';position:absolute;inset:-1px;border-radius:inherit;pointer-events:none;opacity:0;transition:opacity .4s;padding:1px;background:radial-gradient(260px circle at var(--mx,50%) var(--my,50%),#682b3d,transparent 70%);-webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude}
.services article:hover:before,.package:hover:before,form:hover:before{opacity:1}

/* Spring cursor */
.cur{position:fixed;left:0;top:0;width:34px;height:34px;border:1px solid var(--wine);border-radius:50%;pointer-events:none;z-index:250;opacity:0;transition:width .3s var(--ease),height .3s var(--ease),background .3s,opacity .3s;mix-blend-mode:multiply}
.cur.on{opacity:1}.cur.big{width:72px;height:72px;background:#682b3d1c}

/* Footer wordmark */
.bigmark{width:100%;display:flex;justify-content:space-between;overflow:hidden;font:clamp(56px,17.5vw,280px)/.82 var(--serif);letter-spacing:-.04em;color:#f5f0e724;text-transform:uppercase;user-select:none;padding-top:10px}
.bigmark span{display:inline-block}
.mo .bigmark span{transform:translateY(105%);transition:transform 1.2s var(--ease) calc(var(--i)*60ms)}
.mo .bigmark.go span{transform:none}

body.motion-off .wi,body.motion-off .bigmark span{transform:none!important}
body.motion-off .hero .bar-photo{clip-path:none!important}
body.motion-off .pre,body.motion-off .cur{display:none}
@media(hover:none),(pointer:coarse){.cur{display:none}}
@media(prefers-reduced-motion:reduce){.pre,.cur{display:none}.wi,.bigmark span{transform:none!important}.hero .bar-photo{clip-path:none!important}}

