<script>
(()=>{'use strict';

// Fit every clip to its source ratio; never force landscape video into a portrait box.
const reelVideos=[...document.querySelectorAll('.reel-frame video')];
reelVideos.forEach((video,index)=>{
 const frame=video.closest('.reel-frame'),play=document.createElement('button'),time=document.createElement('span');
 play.className='reel-play';play.type='button';play.setAttribute('aria-label','Play '+video.getAttribute('aria-label'));play.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4v16l14-8z"/></svg><span>Watch the film</span>';
 time.className='reel-time';time.setAttribute('aria-hidden','true');frame.append(play,time);
 function metadata(){if(video.videoWidth&&video.videoHeight)video.style.aspectRatio=video.videoWidth+'/'+video.videoHeight;const d=video.duration;if(Number.isFinite(d))time.textContent=Math.floor(d/60)+':'+String(Math.floor(d%60)).padStart(2,'0')}
 video.addEventListener('loadedmetadata',metadata);metadata();
 play.addEventListener('click',async()=>{try{await video.play()}catch{play.querySelector('span').textContent='Try playing again'}});
 video.addEventListener('play',()=>{frame.classList.add('is-playing');reelVideos.forEach(other=>{if(other!==video)other.pause()})});
 video.addEventListener('pause',()=>frame.classList.remove('is-playing'));video.addEventListener('ended',()=>frame.classList.remove('is-playing'));
 video.addEventListener('error',()=>{play.querySelector('span').textContent='Open video';play.onclick=()=>window.open(video.querySelector('source').src,'_blank','noopener')});
});
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;const motionButton=$('.motion-toggle');function setMotion(){document.body.classList.toggle('motion-off',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'Enable motion ▷':'Pause motion Ⅱ';document.documentElement.style.scrollBehavior=paused?'auto':''}setMotion();motionButton.addEventListener('click',()=>{paused=!paused;setMotion()});reduced.addEventListener('change',e=>{paused=e.matches;setMotion()});
const menu=$('.menu'),nav=$('nav');function closeMenu(){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});$$('nav a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
if('IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.1});$$('.reveal').forEach(e=>observer.observe(e))}
let queued=false;function progress(){if(queued)return;queued=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;$('.progress').style.transform=`scaleX(${max>0?scrollY/max:0})`;queued=false})}addEventListener('scroll',progress,{passive:true});addEventListener('resize',progress);progress();
const form=$('#reservation-form');$$('.choose').forEach(b=>b.addEventListener('click',()=>{form.elements.event_type.value=b.dataset.type;$('#reserve').scrollIntoView({behavior:paused?'instant':'smooth'});form.elements.name.focus({preventScroll:true})}));$$('[data-package]').forEach(a=>a.addEventListener('click',()=>{form.elements.package_id.value=a.dataset.package}));
const lightbox=$('#lightbox');$$('.gallery-photo').forEach(b=>b.addEventListener('click',()=>{const source=b.querySelector('img');lightbox.querySelector('img').src=source.src;lightbox.querySelector('img').alt=source.alt;lightbox.showModal()}));lightbox.querySelector('button').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('.submit'),result=$('#form-result');button.disabled=true;button.textContent='Sending your request…';result.textContent='';result.className='';try{const response=await fetch(location.pathname,{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});const data=await response.json();result.textContent=data.message;result.className=data.ok?'success':'error';if(data.ok)form.reset()}catch{result.textContent='Unable to send your request. Please check your connection and try again.';result.className='error'}finally{button.disabled=false;button.innerHTML='Send my event request <span aria-hidden="true">↗</span>';result.focus()}});
$('#check-availability').addEventListener('click',async()=>{const status=$('#availability-result'),button=$('#check-availability');if(['venue_id','date','start','end'].some(k=>!form.elements[k].value)){status.textContent='Choose a venue, date, start time, and end time first.';return}const params=new URLSearchParams({venue:form.elements.venue_id.value,date:form.elements.date.value,start:form.elements.start.value,end:form.elements.end.value});button.disabled=true;status.textContent='Checking your schedule…';try{const response=await fetch(<?= json_encode($base.'availability.php') ?>+'?'+params),data=await response.json();status.textContent=data.message}catch{status.textContent='Unable to check this schedule. Please try again.'}finally{button.disabled=false}});
})();

/* ===== Motion layer ===== */
(()=>{'use strict';
const d=document,root=d.documentElement,$=(s,r=d)=>r.querySelector(s),$$=(s,r=d)=>[...r.querySelectorAll(s)];
if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
const fine=matchMedia('(hover:hover) and (pointer:fine)').matches,off=()=>d.body.classList.contains('motion-off');
root.classList.add('mo');

/* Split headlines into masked words */
function split(el){(function walk(n){[...n.childNodes].forEach(c=>{if(c.nodeType===3){const f=d.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(t=>{if(!t)return;if(/^\s+$/.test(t)){f.append(t);return}const w=d.createElement('span'),i=d.createElement('span');w.className='w';i.className='wi';i.textContent=t;w.append(i);f.append(w)});c.replaceWith(f)}else if(c.nodeType===1)walk(c)})})(el);$$('.wi',el).forEach((i,k)=>i.style.setProperty('--i',k))}
const heads=$$('h1,h2');heads.forEach(split);

/* Reveal on view (h2s + footer wordmark) */
const io='IntersectionObserver'in window?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('go');io.unobserve(e.target)}}),{threshold:.35}):null;
heads.forEach(h=>{if(h.tagName==='H2')io?io.observe(h):h.classList.add('go')});
const ft=$('footer');if(ft){const m=d.createElement('div');m.className='bigmark';m.setAttribute('aria-hidden','true');m.innerHTML=[...'UNCORKED'].map((l,k)=>`<span style="--i:${k}">${l}</span>`).join('');ft.insertBefore(m,$('small',ft));io?io.observe(m):m.classList.add('go')}

/* Stagger siblings */
$$('.cards,.steps,.reel-grid,.product-photo-grid').forEach(g=>[...g.children].forEach((c,k)=>c.style.setProperty('--delay',k*120+'ms')));

/* Loader: counter + curtain, once per session */
const hero=$('.hero');let seen=false;try{seen=sessionStorage.getItem('uc-pre')==='1'}catch{}
function start(){hero&&hero.classList.add('go')}
if(seen||off()){start()}else{
 const pre=d.createElement('div');pre.className='pre';pre.setAttribute('aria-label','Uncorked intro');pre.innerHTML='<div class="pre-n"><span>0</span><small>%</small></div><p>UNCORKED · POP-UP BAR</p><div class="pre-bar"><u></u></div>';
 d.body.append(pre);root.style.overflow='hidden';const skip=d.createElement('button');skip.type='button';skip.className='intro-skip';skip.textContent='Skip intro ↗';pre.append(skip);
 const n=$('.pre-n span',pre),bar=$('u',pre),t0=performance.now(),dur=1500;let fin=false;
 const end=()=>{if(fin)return;fin=true;pre.classList.add('done');root.style.overflow='';try{sessionStorage.setItem('uc-pre','1')}catch{}setTimeout(start,350);setTimeout(()=>pre.remove(),1200)};
 skip.addEventListener('click',end);
 (function step(t){const p=Math.min((t-t0)/dur,1),e=1-Math.pow(1-p,3);n.textContent=Math.round(e*100);bar.style.transform=`scaleX(${e})`;p<1?requestAnimationFrame(step):setTimeout(end,150)})(t0);
 setTimeout(end,4000);
}

/* Hero glow, photo tilt, spotlight borders, magnetic buttons */
if(fine){
 if(hero){const g=d.createElement('div');g.className='glow';hero.prepend(g);hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();hero.style.setProperty('--hx',e.clientX-r.left+'px');hero.style.setProperty('--hy',e.clientY-r.top+'px')})}
 const tilt=(el,deg)=>{el.addEventListener('pointermove',e=>{if(off())return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(900px) rotateY(${x*deg}deg) rotateX(${-y*deg}deg)`});el.addEventListener('pointerleave',()=>el.style.transform='')};
 $$('.bar-photo').forEach(el=>tilt(el,8));$$('.package').forEach(el=>tilt(el,5));
 $$('.services article,.package,form').forEach(el=>el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--mx',e.clientX-r.left+'px');el.style.setProperty('--my',e.clientY-r.top+'px')}));
 $$('.btn').forEach(b=>{b.addEventListener('pointermove',e=>{if(off())return;const r=b.getBoundingClientRect();b.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.25}px,${(e.clientY-r.top-r.height/2)*.35}px)`});b.addEventListener('pointerleave',()=>b.style.transform='')});
}

/* One frame loop: spring cursor, scroll-velocity marquee, hero parallax */
const cur=fine?d.createElement('div'):null;let x=innerWidth/2,y=innerHeight/2,tx=x,ty=y;
if(cur){cur.className='cur';cur.setAttribute('aria-hidden','true');d.body.append(cur);
 addEventListener('pointermove',e=>{tx=e.clientX;ty=e.clientY;cur.classList.add('on')},{passive:true});
 d.documentElement.addEventListener('pointerleave',()=>cur.classList.remove('on'));
 d.addEventListener('pointerover',e=>cur.classList.toggle('big',!!e.target.closest('a,button,summary,video,.bar-photo')))}
const mq=$('.marquee>div'),copy=$('.bar-hero-copy'),curves=$('.ambient-curves');let last=scrollY,v=0;
(function loop(){
 if(cur){x+=(tx-x)*.18;y+=(ty-y)*.18;cur.style.transform=`translate(${x}px,${y}px) translate(-50%,-50%)`}
 const dy=Math.abs(scrollY-last);last=scrollY;v+=(Math.min(dy,80)-v)*.1;
 if(mq&&!off()){const a=mq.getAnimations()[0];if(a)a.playbackRate=1+v*.3}
 if(!off()){const s=Math.min(scrollY,900);if(copy&&!hero.closest('.has-cinema'))copy.style.transform=`translateY(${s*.12}px)`;if(curves)curves.style.transform=`rotate(${s*.015}deg)`}
 requestAnimationFrame(loop)
})();
})();

(()=>{const d=document,cta=d.querySelector('.sticky-cta'),res=d.querySelector('#reserve'),hero=d.querySelector('.hero');
function chk(){if(!cta)return;const r=res.getBoundingClientRect(),hh=hero?hero.offsetHeight*.8:500,journey=hero?.closest('.hero-journey'),inJourney=journey?.classList.contains('has-cinema')&&journey.getBoundingClientRect().bottom>innerHeight;cta.classList.toggle('show',!inJourney&&scrollY>hh&&!(r.top<innerHeight*.7&&r.bottom>0))}
addEventListener('scroll',chk,{passive:true});chk();
const rm=matchMedia('(prefers-reduced-motion: reduce)').matches;
d.querySelectorAll('[data-count]').forEach(el=>{const to=+el.dataset.count,suf=el.dataset.suffix||'';if(rm||!('IntersectionObserver'in window))return;el.textContent='0'+suf;const o=new IntersectionObserver(es=>{if(!es[0].isIntersecting)return;o.disconnect();const t0=performance.now();(function f(t){const p=Math.min((t-t0)/1400,1);el.textContent=Math.round(to*(1-Math.pow(1-p,3)))+suf;if(p<1)requestAnimationFrame(f)})(t0)},{threshold:.6});o.observe(el)});
})();

(()=>{const d=document,rm=matchMedia('(prefers-reduced-motion: reduce)').matches,off=()=>d.body.classList.contains('motion-off'),hero=d.querySelector('.hero');
const sw=d.querySelector('.swap-w');if(sw&&!rm){const W=['weddings','birthdays','debuts','corporate events','private parties'];let i=0,cur=sw.querySelector('b');setInterval(()=>{if(d.hidden||off())return;i=(i+1)%W.length;const n=d.createElement('b'),old=cur;n.textContent=W[i];n.style.transform='translateY(100%)';n.style.opacity=0;sw.append(n);n.getBoundingClientRect();n.style.transform='none';n.style.opacity=1;old.style.transform='translateY(-100%)';old.style.opacity=0;setTimeout(()=>old.remove(),800);cur=n},2400)}
if(hero&&matchMedia('(hover:hover) and (pointer:fine)').matches&&!rm){hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();hero.style.setProperty('--rx',((e.clientX-r.left)/r.width-.5).toFixed(3));hero.style.setProperty('--ry',((e.clientY-r.top)/r.height-.5).toFixed(3))});hero.addEventListener('pointerleave',()=>{hero.style.setProperty('--rx',0);hero.style.setProperty('--ry',0)});
d.querySelectorAll('.tile').forEach(el=>{el.addEventListener('pointermove',e=>{if(off())return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(900px) rotateY(${x*7}deg) rotateX(${-y*7}deg)`});el.addEventListener('pointerleave',()=>el.style.transform='')})}
const cv=d.querySelector('.bubbles');if(cv&&!rm){const ctx=cv.getContext('2d'),dpr=Math.min(devicePixelRatio||1,2);let W,H,P=[],run=true;
function size(){const r=cv.parentElement.getBoundingClientRect();W=r.width;H=r.height;cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}size();addEventListener('resize',size);
const mk=init=>({x:Math.random()*W,y:init?Math.random()*H:H+20,r:2+Math.random()*7,v:.25+Math.random()*.7,s:Math.random()*6.28,a:.25+Math.random()*.4});
for(let i=0;i<(innerWidth<760?22:46);i++)P.push(mk(true));
if('IntersectionObserver'in window)new IntersectionObserver(e=>run=e[0].isIntersecting).observe(cv);
(function f(t){requestAnimationFrame(f);if(!run||off())return;ctx.clearRect(0,0,W,H);P.forEach((p,i)=>{p.y-=p.v;p.x+=Math.sin(t/900+p.s)*.35;if(p.y<-20)P[i]=mk();ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.283);ctx.fillStyle='rgba(255,255,255,'+p.a*.3+')';ctx.fill();ctx.strokeStyle='rgba(103,69,80,'+p.a+')';ctx.lineWidth=1;ctx.stroke();ctx.beginPath();ctx.arc(p.x-p.r*.3,p.y-p.r*.3,p.r*.22,0,6.283);ctx.fillStyle='rgba(255,255,255,'+p.a+')';ctx.fill()})})()}
})();

(()=>{const d=document,f=d.querySelector('#reservation-form'),go=d.querySelector('#qb-go');if(!f||!go)return;
go.addEventListener('click',()=>{const t=d.querySelector('#qb-type').value,dt=d.querySelector('#qb-date').value,g=d.querySelector('#qb-guests').value;
if(t)f.elements.event_type.value=t;if(dt)f.elements.date.value=dt;if(g)f.elements.guests.value=g;
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches||d.body.classList.contains('motion-off');
d.querySelector('#reserve').scrollIntoView({behavior:reduce?'auto':'smooth'});setTimeout(()=>f.elements.name.focus({preventScroll:true}),reduce?0:700)})})();

(()=>{const d=document,rm=matchMedia('(prefers-reduced-motion: reduce)').matches;
d.querySelectorAll('img').forEach(i=>{const bad=()=>{i.style.visibility='hidden'};i.addEventListener('error',bad);if(i.complete&&i.naturalWidth===0&&i.src)bad()});
const hs=d.querySelector('.hs');
if(hs){const tr=hs.querySelector('.hs-track'),pin=hs.querySelector('.hs-pin'),bar=hs.querySelector('.hs-bar i'),cards=[...tr.children],wide=matchMedia('(min-width:900px)'),motion=matchMedia('(prefers-reduced-motion:reduce)'),header=d.querySelector('header'),label=d.createElement('span');let dist=0,on=false,queued=false;label.className='hs-counter';label.setAttribute('aria-hidden','true');pin.querySelector('.section-head>div').append(label);
const update=()=>{queued=false;let p=0;if(on){const top=header.getBoundingClientRect().height,r=hs.getBoundingClientRect();p=Math.min(Math.max((top-r.top)/Math.max(dist,1),0),1);tr.style.transform='translateX('+(-p*dist)+'px)';bar.style.transform='scaleX('+p+')';cards.forEach(c=>{const r=c.getBoundingClientRect(),amount=Math.max(0,Math.min(1,(innerWidth-r.left)/Math.min(r.width,320)));c.style.opacity=String(.18+amount*.82);c.style.transform='translateY('+((1-amount)*28)+'px) scale('+(.95+amount*.05)+')'})}else{p=Math.max(0,Math.min(1,pin.scrollLeft/Math.max(1,pin.scrollWidth-pin.clientWidth)))}label.textContent=String(Math.min(cards.length,Math.floor(p*(cards.length-1))+1)).padStart(2,'0')+' / '+String(cards.length).padStart(2,'0')};
const queue=()=>{if(!queued){queued=true;requestAnimationFrame(update)}};
const size=()=>{on=wide.matches&&!motion.matches&&!d.body.classList.contains('motion-off');hs.classList.toggle('on',on);tr.style.transform='';cards.forEach(c=>{c.style.transform='';c.style.opacity=''});dist=Math.max(0,tr.scrollWidth-innerWidth);hs.style.height=on?(dist+pin.getBoundingClientRect().height)+'px':'';pin.querySelector('.section-head>p').textContent=on?'Keep scrolling. The story moves sideways →':'Swipe sideways to explore →';queue()};
size();addEventListener('resize',size);addEventListener('scroll',queue,{passive:true});pin.addEventListener('scroll',queue,{passive:true});wide.addEventListener('change',size);motion.addEventListener('change',size);new MutationObserver(size).observe(d.body,{attributes:true,attributeFilter:['class']});hs.querySelectorAll('img').forEach(i=>i.addEventListener('load',size));
}
if(rm)return;
const intro=d.querySelector('.experience .intro');
if(intro){const ws=[];(function walk(n){[...n.childNodes].forEach(c=>{if(c.nodeType===3){const f=d.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(t=>{if(!t)return;if(/^\s+$/.test(t)){f.append(t);return}const e=d.createElement('span');e.className='sw';e.textContent=t;ws.push(e);f.append(e)});c.replaceWith(f)}else if(c.nodeType===1)walk(c)})})(intro);
const fill=()=>{const r=intro.getBoundingClientRect(),p=Math.min(Math.max((innerHeight*.85-r.top)/(innerHeight*.45+r.height),0),1);ws.forEach((w,i)=>w.classList.toggle('on',i/ws.length<p))};
addEventListener('scroll',fill,{passive:true});fill()}
})();

/* ===== Uncorked camera journey: two pinned sequences total, including services. ===== */
(()=>{'use strict';
const d=document,track=d.querySelector('.hero-journey'),hero=track?.querySelector('.hero');if(!hero)return;
const copy=hero.querySelector('.bar-hero-copy'),visual=hero.querySelector('.bar-hero-visual'),form=hero.querySelector('.glass-book'),film=hero.querySelector('.journey-film'),pictures=[...film.querySelectorAll('.journey-image')],panels=[...film.querySelectorAll('.journey-copy')],chapters=[...hero.querySelectorAll('[data-scene]')],line=hero.querySelector('.journey-line i'),actions=copy.querySelector('.actions'),quote=hero.querySelector('.journey-quote'),header=d.querySelector('header'),orbit=film.querySelector('.journey-orbit');
const wide=matchMedia('(min-width:900px) and (min-height:650px)'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
const clamp=n=>Math.max(0,Math.min(1,n)),range=(p,a,b)=>clamp((p-a)/(b-a)),smooth=n=>n*n*(3-2*n);
let enabled=false,top=0,distance=1,current=0,raf=0,lastIndex=-1,lastTick=0;
function render(p){
 const push=smooth(range(p,.015,.32)),original=1-smooth(range(p,.15,.31));
 copy.style.opacity=String(1-smooth(range(p,.02,.2)));copy.style.transform='translate3d('+(-push*120)+'px,0,0)';
 visual.style.opacity=String(original);visual.style.transform='translate3d('+(-push*innerWidth*.22)+'px,'+(push*28)+'px,0) scale('+(1+push*1.15)+')';
 visual.querySelectorAll('.flourish-photo,.flourish-seal').forEach(e=>e.style.opacity=String(1-range(p,0,.1)));
 form.style.opacity=String(1-range(p,0,.12));form.style.transform='translate3d(0,'+(range(p,0,.15)*32)+'px,0)';
 actions.inert=p>.19;visual.inert=p>.18;form.inert=p>.1;
 film.style.opacity=String(smooth(range(p,.13,.32)));
 const second=smooth(range(p,.42,.61)),third=smooth(range(p,.74,.9));
 pictures[1].style.clipPath='inset(0 '+((1-second)*100)+'% 0 0)';
 pictures[2].style.clipPath='inset(0 0 0 '+((1-third)*100)+'%)';
 pictures[0].querySelector('img').style.transform='scale('+(1.05+range(p,.2,.65)*.15)+') translate3d('+(-range(p,.2,.65)*3)+'%,0,0)';
 pictures[1].querySelector('img').style.transform='scale('+(1.22-range(p,.42,.78)*.22)+') translate3d('+(3-range(p,.42,.78)*3)+'%,0,0)';
 pictures[2].querySelector('img').style.transform='scale('+(1.16-range(p,.74,1)*.13)+')';
 const visibility=[smooth(range(p,.21,.29))*(1-smooth(range(p,.44,.5))),smooth(range(p,.44,.5))*(1-smooth(range(p,.76,.82))),smooth(range(p,.76,.82))];
 panels.forEach((panel,i)=>{const a=visibility[i],sign=i===1?-1:1;panel.style.opacity=String(a);panel.style.transform='translate3d('+(sign*(1-a)*70)+'px,calc(-50% + '+((1-a)*20)+'px),0)'});
 orbit.style.transform='rotate('+(p*100-20)+'deg) translate3d('+(-p*10)+'%,0,0)';
 hero.classList.toggle('cinema-dark',p>.2);quote.inert=p<=.2;line.style.transform='scaleX('+p+')';
 const index=p<.47?0:p<.8?1:2;
 if(index!==lastIndex){lastIndex=index;hero.dataset.cinemaChapter=String(index+1);chapters.forEach((b,i)=>{if(i===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}
}
function tick(now){raf=0;if(!enabled||d.hidden)return;const target=clamp((scrollY-top)/distance),elapsed=lastTick?Math.max(16,Math.min(1000,now-lastTick)):1000;lastTick=now;current+=(target-current)*(1-Math.exp(-elapsed/85));if(Math.abs(target-current)<.0004)current=target;render(current);if(current!==target)raf=requestAnimationFrame(tick)}
function queue(){if(enabled&&!raf)raf=requestAnimationFrame(tick)}
function size(){
 const wasEnabled=enabled;enabled=wide.matches&&!reduced.matches&&!d.body.classList.contains('motion-off');
 const height=header.getBoundingClientRect().height;
 track.style.setProperty('--journey-top',height+'px');track.style.setProperty('--journey-height',(innerHeight-height)+'px');distance=innerHeight*2.6;track.style.setProperty('--journey-distance',distance+'px');track.classList.toggle('has-cinema',enabled);
 if(enabled){top=track.getBoundingClientRect().top+scrollY-height;current=clamp((scrollY-top)/distance);render(current);queue()}
 else if(wasEnabled){cancelAnimationFrame(raf);raf=0;[copy,visual,form].forEach(e=>{e.style.opacity='';e.style.transform=''});visual.querySelectorAll('.flourish-photo,.flourish-seal').forEach(e=>e.style.opacity='');[actions,visual,form,quote].forEach(e=>e.inert=false);hero.classList.remove('cinema-dark')}
}
chapters.forEach(b=>b.addEventListener('click',()=>{if(enabled)scrollTo({top:top+distance*Number(b.dataset.scene),behavior:'smooth'})}));
addEventListener('scroll',queue,{passive:true});addEventListener('resize',size);wide.addEventListener('change',size);reduced.addEventListener('change',size);d.addEventListener('visibilitychange',queue);
new MutationObserver(size).observe(d.body,{attributes:true,attributeFilter:['class']});
if('ResizeObserver'in window)new ResizeObserver(size).observe(header);
if(d.fonts?.ready)d.fonts.ready.then(size);size();
})();

</script></body></html>
